create table if not exists clients(id bigint generated by default as identity primary key,name text not null,phone text,created_at timestamptz default now());
create table if not exists vehicles(id bigint generated by default as identity primary key,plate text not null,client_name text,type text,created_at timestamptz default now());
create table if not exists washes(id bigint generated by default as identity primary key,client_name text,plate text,service text,amount numeric default 0,created_at timestamptz default now());
create table if not exists cash(id bigint generated by default as identity primary key,type text,amount numeric default 0,description text,created_at timestamptz default now());
create table if not exists employees(id bigint generated by default as identity primary key,name text not null,role text,created_at timestamptz default now());
create table if not exists services(id bigint generated by default as identity primary key,name text not null,price numeric default 0,created_at timestamptz default now());